function.arguments:
{"command": "python3 - <<'EOF'
import json
runs = [json.loads(l) for l in open('/workspace/out/cde_runs.jsonl')]
last = {}
for r in runs: last[r['target_id']] = r   # last run per target = worksheet of record
for tid in sorted(last):
    r = last[tid]
    print(f"{tid} lvl={r['cde_level']} occ={r['occupancy_basis']} est={r['nc_casualty_estimate']} ncv={r['ncv']} auth={r['approval_authority']} nsl={r['nsl_within_cer']} cmd='{r['cmd']}'")
print("total runs:", len(runs))
EOF"}
